/// Ways to get a session. The snapshot and project always come from a response that already
/// pairs them, so the overloads below take those responses rather than leaving a caller to
/// unpack the pair and risk crossing a snapshot with another snapshot's project.
[<Extension>]
type SessionConstructors =

    /// A session on `channel` over a snapshot and project named directly.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: int, project: string) =
        { Transport = this; Snapshot = snapshot; Project = project }

    /// A session on one project of a snapshot, named by id. A snapshot can hold several, so the
    /// project is not inferred.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: CreateSnapshotResponse, project: string) =
        { Transport = this; Snapshot = snapshot.Snapshot; Project = project }

    /// A session on the program a snapshot created (`createPrograms`) when it created exactly one,
    /// and otherwise on the snapshot's only project. Raises when neither names a single project, so
    /// a caller opening one program never has to index into the response.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: CreateSnapshotResponse) =
        match snapshot.Operation.CreatedPrograms, snapshot.Projects with
        | ValueSome [| program |], _ -> { Transport = this; Snapshot = snapshot.Snapshot; Project = program }
        | _, [| project |] -> { Transport = this; Snapshot = snapshot.Snapshot; Project = project.Id }
        | _, projects ->
            failwithf "the snapshot holds %d projects, so name the one to open a session on" projects.Length

    /// A session on `mailbox` over a snapshot and project named directly.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: int, project: string) =
        { Transport = this; Snapshot = snapshot; Project = project }

    /// A session on one project of a snapshot, named by id. A snapshot can hold several, so the
    /// project is not inferred.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: CreateSnapshotResponse, project: string) =
        { Transport = this; Snapshot = snapshot.Snapshot; Project = project }

    /// A session on the program a snapshot created (`createPrograms`) when it created exactly one,
    /// and otherwise on the snapshot's only project. Raises when neither names a single project, so
    /// a caller opening one program never has to index into the response.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: CreateSnapshotResponse) =
        match snapshot.Operation.CreatedPrograms, snapshot.Projects with
        | ValueSome [| program |], _ -> { Transport = this; Snapshot = snapshot.Snapshot; Project = program }
        | _, [| project |] -> { Transport = this; Snapshot = snapshot.Snapshot; Project = project.Id }
        | _, projects ->
            failwithf "the snapshot holds %d projects, so name the one to open a session on" projects.Length

